WITH unpacked AS (SELECT id, created_at, ship_to, ARRAY_CONTAINS(coupon_codes, 'BUNDLE') AS used_bundle, SIZE(items) AS num_items, COALESCE(attributes['utm_source'], 'direct') AS utm_source_or_default, FORALL(items, i -> i.qty <= 5) AS all_small_qty FROM carts WHERE HOUR(created_at) BETWEEN 10 AND 16) SELECT CASE WHEN num_items >= 3 THEN 'HIGH' ELSE 'LOW' END AS num_items_tier, DATE_TRUNC('DAY', created_at) AS activity_day, COUNT(DISTINCT utm_source_or_default) AS distinct_utm_source_or_defaults, ROUND(AVG(num_items), 2) AS avg_num_items, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min FROM unpacked GROUP BY ROLLUP (CASE WHEN num_items >= 3 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('DAY', created_at)) HAVING COUNT(DISTINCT utm_source_or_default) >= 1 ORDER BY num_items_tier
